@pytest.mark.parametrize("mcp,hybrid,deepseek", [(False, False, False), (False, True, False), (True, False, False), (True, True, False), (True, False, True)]) def test_os_external_cli_cold_then_independent_warm_without_http_or_search_key(tmp_path, monkeypatch, mcp, hybrid, deepseek): argv = _subprocess_inputs(tmp_path, monkeypatch, mcp=mcp, hybrid=hybrid, deepseek=deepseek) cold = _external_spawn(tmp_path, argv, stub=True, label="cold") assert cold.returncode == 0, cold.stdout[-3000:] + cold.stderr[-3000:] first = json.loads((tmp_path / "result.json").read_text("utf-8")) receipt = first["execution_receipts"]["IQS_05"] sends = _external_sends(tmp_path) expected = ["initialize", "notifications/initialized", "tools/list", "tools/call", "model"] if mcp else ["search", "model"] assert [row["kind"] for row in sends] == expected assert len({row["pid"] for row in sends}) == 1 and sends[0]["pid"] != os.getpid() assert sends[-1]["has_context"] and sends[-1]["native_tools"] == hybrid if deepseek: assert sends[-1]["thinking"] == {"effort": "high"} assert receipt["search_status"] == "executed" and first["answers"]["IQS_05"]["score"] == 6 assert "SYNTHETIC_PRIVATE_SESSION" not in json.dumps(first) assert "PRIVATE_CHILD_THINKING" not in json.dumps(first) store = _external_store(tmp_path) before = store.get_quick_scan_budget_status("quick-scan-test-policy") assert before["requests"] == len(expected) and before["spent_micros"] == (22000 if mcp else 13000) assert before["reserved_micros"] == 0 warm = _external_spawn(tmp_path, argv, stub=False, label="warm") > assert warm.returncode == 0, warm.stdout[-3000:] + warm.stderr[-3000:] E AssertionError: b'INFO - ======================================================================\r E INFO - \xe5\x85\xac\xe5\x8f\xb8\xe5...\r E ValueError: external_search_routes_unadmitted: brave-primary:credential_env_unset,*:no_admitted_external_route\r E ' E assert 1 == 0 E + where 1 = CompletedProcess(args=['C:\\Miniconda\\python.exe', '-B', '-X', 'utf8', 'C:\\Users\\郑曾波\\Projects\\invest-quick-scan\\...r: external_search_routes_unadmitted: brave-primary:credential_env_unset,*:no_admitted_external_route\r\n', stderr=b'').returncode
